import { addProfileBadge, BadgePosition, ProfileBadge } from "./Badges";

interface CustomBadge {
    userId: string;
    text: string;
    image: string;
}

const BADGES: CustomBadge[] = [
    { userId: "368517278209409045", text: "jay", image: "data:image/png;base64," },
    { userId: "1354503871757553737", text: "chris", image: "data:image/png;base64," }
];

declare global {
    var __slipcordCustomBadgesInitialized: boolean | undefined;
}

if (!globalThis.__slipcordCustomBadgesInitialized) {
    globalThis.__slipcordCustomBadgesInitialized = true;

    for (const { userId, text, image } of BADGES) {
        addProfileBadge({
            id: `slipcord_badge_${userId}`,
            iconSrc: image,
            description: text,
            position: BadgePosition.START,
            shouldShow: args => args.userId === userId
        } satisfies ProfileBadge);
    }
}
